#include <stdint.h>
#include <main.h>
#include <clock.h>
#include <pwm.h>
#include <butled.h>
#include <adc.h>
#include <tick.h>
#include <i2c.h>
#include <eeprom.h>
#include <synth.h>
#include <midi.h>
#include <lfo.h>
#include <string.h>

__attribute__((section(".fwver_section"))) const uint8_t fw_version[] = "FW v1.0 SxLab";

#define EEPROM_SIZE 199
#define EEPROM_ALIGNED_SIZE 208
const uint8_t eeprom_defaults[EEPROM_ALIGNED_SIZE] = {
197, 8, 72, 8, 149, 9, 120, 7, 17, 14, 102, 10, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 166, 4, 12, 7, 18, 9, 79, 4, 164, 4, 104, 6, 1, 0, 0, 0, 8, 0, 0, 0, 52, 0, 0, 32,			// Preset M1
165, 8, 72, 8, 212, 9, 75, 4, 0, 0, 104, 7, 255, 7, 255, 7, 104, 6, 179, 10, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 1, 0, 0, 0, 4, 0, 0, 0, 52, 0, 0, 32,			// Preset M2
134, 7, 65, 8, 186, 8, 222, 2, 117, 6, 120, 8, 0, 0, 255, 15, 255, 15, 255, 15, 110, 7, 113, 4, 255, 15, 143, 8, 255, 15, 255, 7, 66, 11, 255, 7, 1, 0, 0, 0, 2, 0, 0, 0, 52, 0, 0, 32,		// Preset M3
197, 8, 72, 8, 149, 9, 120, 7, 17, 14, 102, 10, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 255, 7, 166, 4, 12, 7, 18, 9, 79, 4, 164, 4, 104, 6, 1, 0, 0, 0, 8, 0, 0, 0, 52, 0, 0, 32,			// Preset X
0xFA, 0xCE, // Check
0xFF,		// Midi channel
0x00,		// Preset X loaded
0b00010000, // CWE: Lights 1: Min speed christmas, 1/4 brightness
0x40,		// CWE: Lights 2: Green-ish, max saturation
0 // Default synth engine!
};

void SystemInit() {
	//RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;

}

int main(void)
{
	RCC->APB1ENR |= RCC_APB1ENR_PWREN;
	RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;
	RCC->AHBENR |= RCC_AHBENR_GPIOAEN;


	clock_configure();
	_delayMs(1);

	// This. Is. Stupid.
	memcpy((uint32_t*)0x20000000, (uint32_t*)0x8002000, 4*48);
	SYSCFG->CFGR1 |= 0b11 << SYSCFG_CFGR1_MEM_MODE_Pos;

	butled_configure();
	_delayMs(10);
	adc_configure();
	i2c1_init();

	// Resets
	 if(but_check(BUTLED_SAVE) && but_check(BUTLED_DRONE)) {
		uint8_t make_reset = 1;
		for(uint16_t i = 0; i < 1000; i++) {
			if(!(but_check(BUTLED_SAVE) && but_check(BUTLED_DRONE))) {
				make_reset = 0;
				break;
			}
			_delayMs(1);
		}

		if(make_reset) {
			eeprom_write8(EEPROM_HAS_PRESET3, 0);
			eeprom_wait_available(1000);
			butled_animation = 0b11111;
			butled_timer = 500;
			but_ignoreNext(BUTLED_SAVE);
			but_ignoreNext(BUTLED_DRONE);
		}

	} else if(but_check(BUTLED_M1) && but_check(BUTLED_M2) && but_check(BUTLED_M3)) {
		uint8_t make_reset = 1;
		for(uint16_t i = 0; i < 1000; i++) {
			if(!(but_check(BUTLED_M1) && but_check(BUTLED_M2) && but_check(BUTLED_M3))) {
				make_reset = 0;
				break;
			}
			_delayMs(1);
		}

		if(make_reset) {
			for(uint16_t i = 0; i < EEPROM_ALIGNED_SIZE; i+= 16) {
				eeprom_write_buffer(i, eeprom_defaults + i, 16);
				eeprom_wait_available(100);
			}
			butled_animation = 0b11111;
			butled_timer = 500;
		}

		but_ignoreNext(BUTLED_M1);
		but_ignoreNext(BUTLED_M2);
		but_ignoreNext(BUTLED_M3);
	} else if(but_check(BUTLED_M1)) {
		// Do nothing.
		but_ignoreNext(BUTLED_M1);
	} else if (but_check(BUTLED_M2)) {
		// Do nothing.
		but_ignoreNext(BUTLED_M2);
	} else if (but_check(BUTLED_M3)) {
		but_ignoreNext(BUTLED_M3);
	}

	// Buttons ignore
	if (but_check(BUTLED_M1)) {but_ignoreNext(BUTLED_M1);}
	if (but_check(BUTLED_M2)) {but_ignoreNext(BUTLED_M2);}
	if (but_check(BUTLED_M3)) {but_ignoreNext(BUTLED_M3);}
	if (but_check(BUTLED_DRONE)) {but_ignoreNext(BUTLED_DRONE);}
	if (but_check(BUTLED_SAVE)) {but_ignoreNext(BUTLED_SAVE);}

	// EEPROM error check
	eeprom_wait_available(300);
	if(i2c1_get_error() != 0) {
		uint32_t b = 0;
		for(uint16_t i = 0; i < 1000; i++) {
			uint8_t flash = ((b >> 6) & 0b1) == 0 ? 1 : 0;
			if(flash) {
				for(uint8_t i = 0; i < 6; i++) {
					*PWM_LEDS[i] = 1023;
				}
			} else {
				for(uint8_t i = 0; i < 6; i++) {
					*PWM_LEDS[i] = 0;
				}
			}
			b+=1;
			_delayMs(1);
		}
		_delayMs(500);
		NVIC_SystemReset();
	}
	_delayMs(10);

	// Easter eggs
	uint8_t all_pots_low = 1;
	/*
	for(uint8_t i = 0; i < ADC_DATA_SIZE; i++) {
		if (adcData[i] > 400) {
			all_pots_low = 0;
		}
	}
	*/

	if (all_pots_low && but_check(BUTLED_M1)) {
		_synth_easter_square = 1;
	}
	if (all_pots_low && but_check(BUTLED_M2)) {
		_synth_easter_tuning = 1;
	}
	if (all_pots_low && but_check(BUTLED_DRONE)) {
		_synth_easter_lfohp = 1;
	}

	// Continue init. LFO init, midi init, synth reset
	lfo_sync_configure();
	_midi_own_channel = eeprom_read8(EEPROM_MIDI_CHAN);
	midi_configure();
	synth_reset_midi();

	//_delayMs(10);

	// Load preset zero (preset 3)?
	if(eeprom_read8(EEPROM_HAS_PRESET3)) {
		synth_load_preset(3);
	} else {
		_synth_drone = 1;
		for(uint8_t i = 0; i < 9; i++) {
			_synth_knob_active[i] = 1;
			//_synth_knob[i] = adcData[i];
		}
	}

	// Set synth engine
	//eeprom_wait_available(1000);
	//synth_set_engine(eeprom_read8(EEPROM_SYNTH_ENGINE));
	synth_set_engine(0);
	synth_set_engine(0xFF);
	eeprom_wait_available(1000);

	// Configure tick (interface), wait a bit, enable sound output
	tick_configure();
	_delayMs(5);
	pwm_configure();


    /* Loop forever */
	for(;;) {
		__WFI();
	}
}

